NIGHT_LOADED({"seed":1065,"generated_at":"2026-10-21T06:00:00Z","chain":[1,4,3,2,5],"frame":{"collector":"J.D.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.D.","note_final":"Goed opgeborgen. Morgen om negen. — J.D.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.D.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.D.","initials":"J.D.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.D.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":6,"drawers":[{"id":"1-1","type":"P2","difficulty":2.9387,"rank":0.0523,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"WEV001201","role":"target","render":{"description":"Voorspellingen dat zieke man zal genezen, eerst met wit paard en later met zwart paard ploegen, en dat het zwarte paard de lijkwagen zal trekken, komen uit. De paarden die eerst voor de lijkwagen worden gespannen weigeren, zodat het zwarte paard moet worden ingespannen.","place":null,"prov":"Gr.","year":1962,"code":"SINSAG 0487","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43204","original":"Voorloop. \nSchoenmaker vertelt.\n\nOal Kamies noast ons was de haile winter al aon 't sukkeln.\n't Gung dan veur-, dan achteroet,\nBuurman Wessels was 't er op 'n dag hèn west te kieken, hou d' oale 't muik.\n\"Kamies gait achteroet, hai hoal 't nich meer,\" zee hai.\nMoar opa, oal Steffen, zee.\n\"Nee Wessels, Kamies wordt weer beter.\nHai hef nou 'n wit peerd. En 't volgend veurjoar plougt hai 't land mit 'n zwaarde. \nDat zwaarde peerd brengt hum vot.\" \n't Widde wör verkoft en 'n zwaarde kwam d'r veur in de ploats.\nEen buurman hef hiermit de grond pluigd.\nVolgende zömmer störf Kamies.\nVeur de woagen zol 'n peerd van de buren.\nKamies zien aigen har er nog nooit veur west en doarum wol ze hom laiver nich broeken. …","lang":"Standaardnederlands; Gronings","front":"original"},"home":"1-1"},{"id":"c2","story_id":"WEV000905","role":"helper","render":{"description":"Voordat er een weg is horen van geluid van een hondekar en blaffen van honden.","place":"Ter Apel","prov":"Gr.","year":1962,"code":"SINSAG 0487","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43087","original":"Maar wel is het waar, dat veel mensen in het veen een hondekar hebben horen ratelen. Ook hoorden ze de hond blaffen.\nLang voor er een weg was en voor er later inderdaad een hondekar langs trok.","lang":"Standaardnederlands","front":"original"},"home":"1-1","geo":[52.87667,7.05972]},{"id":"c3","story_id":"WEV006906","role":"helper","render":{"description":"Voorspelling dat er eens veel soldaten zouden komen met wagens zonder paarden. Bij de intocht van de Candadezen in 1945 herinnert iemand zich dit.","place":"Vriescheloo","prov":"Gr.","year":1963,"code":"SINSAG 0487","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43580","original":"Veurloop.\nt Is n hail zet leden. Oabram zee es n moal: “Hier koomt nog ais n haile bult seldoatn. Ik zai ze bie t hoes van H. en bie K en op t haim van Z. Zai hebt woagens bie zuk zunder peerden.\n Toun in 1945 de Canadezen kwamen, was dr nog aine oale, dei zuk dat vertelsel van de spoukkieker in t zin schoot. Hai lag op berre en kun nait best wat zegn, omdat e verlamd was. \nMoar zoveul begreepn wie wel van zien “hoi, hoi”, dat e zegn wol:“Oabram zee t ja al?”","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.06833,7.11389]},{"id":"c4","story_id":"WEV008709","role":"helper","render":{"description":"'s Avonds lawaai in de paardestal is voorteken dat paard iets kapot zal trappen.","place":"Wessinghuizen","prov":"Gr.","year":1965,"code":"SINSAG 0487","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/45305","original":"t Gebeurde wol is, dat ze s oavends wat in t peerdstaal heurden. Kiekn deden ze maistied nich, man ze wuzzen wol, dat t peerd gauw wat stukn hou-en zol; door was t n veurbeduudsel van.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.0525,7.075]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Wessinghuizen.","Zoek Jipsingboertange op de kaart."],"lock":{"kind":"place","target_geo":[52.965,7.10139],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Jipsingboertange"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.3058,"rank":0.6075,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ046312","role":"member","render":{"description":"Nooit 's nachts middenop de weg rennen: er kan een lijkstoet passeren.","place":"Surhuisterveen","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24424","original":"Wy woarden altyd warskôge: rin noait midden op 'e wei by joun of by nacht, hwant der kin us in lykstaesje passeare.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c2","story_id":"CJ102104","role":"member","render":{"description":"Sommigen moesten 's nachts het bed uit om lijkstoeten te zien. Je moest 's nachts nooit midden op de weg rennen.","place":"Augustinusga","prov":"Fr.","year":1973,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37102","original":"Yn 'e Harkema en yn Stiensgea ha 'k wol guon kend dy't nachts fan bêd moesten om lykstaesjes to sjen.\nMen moest nachts noait midden op 'e wei rinne.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c3","story_id":"KOOIJMAN2266","role":"intruder","render":{"description":"Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","place":"Heesselt","prov":"Gld.","year":1963,"code":"SINSAG 0333","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/127631","original":"Dat weet ik ook nog. Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","lang":"Standaardnederlands","front":"original"},"home":"cab:4"},{"id":"c4","story_id":"CJ052415","role":"member","render":{"description":"De verteller vertelt over twee mannen die vaak lijkstoeten zagen. Je moet nooit middenop de weg lopen, omdat een onzichtbare lijkstoet je van de weg af kan drijven.","place":"Surhuisterveen","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25234","original":"Douwe Stavasius fan Grinzer Pein seach lykstaesjes.\nBoardzer Bruining fan Boelensloane ek. Dy leeft noch.\nMen mat noait midden op 'e wei rinne, hwant der kin us in lykstaesje oankomme, sûnder dat men it sjocht. Dan wurde jo fan 'e wei ôfsmiten.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Heesselt hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":4},"on_success":{"trail_note":0,"unlock_cabinet":4,"stack":["c1","c2","c4"]}},{"id":"1-3","type":"R1","difficulty":1.1037,"rank":0.1339,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"CJ083803","role":"omen","render":{"description":"Iemand voorspelt dat een familielid zes weken later zal sterven. De voorspelling klopt precies.","place":"Eastermar","prov":"Fr.","year":1969,"code":"SINSAG 0489","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32807","original":"Yn 'e famylje fan myn wiif to Burgumerheide wie ien tige min. De famylje kom delsetten. (Mar hy is wer better woarn).\nDoe sei ien fan 'e famyljeleden: \"Mei seis wiken binne wy wer byinoar.\"\nOp 'e kop om't ôf, krekt seis wiken letter stoar der in broer fan skoanheit. Dat wie Sjouke Dykstra.\nDyselde hie 't dus wol goed sjoen.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CJ103103","role":"omen","render":{"description":"Dezelfde maat voorspelde eens een brand, die zes weken later gebeurde, toen de bliksem insloeg.","place":"Jistrum","prov":"Fr.","year":1973,"code":"SINSAG 0491","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37196","original":"Mei dyselde maet wie ik to Kûkherne op in plaets fan 'e Veenlands. Der wenne in boer op, dat wie in Hoekstra. Dy hie in soan: Bouwe Hoekstra.\nMyn maet sei tsjin Bouwe: \"Dizze plaets brânt skielk ôf.\"\nSeis wiken letter gebeurde it. De wjerljocht sloech yn. Myn maet hie him fan tofoaren al yn 'e brân sjoen.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c3","story_id":"KOOIJMAN1276","role":"omen","render":{"description":"Als er iemand op vrijdag of zaterdag gestorven was, dan werd het niet begraven. Als dat lijk op zondag boven aarde stond, dan zou er in het dorp binnen zes weken nog iemand overlijden.","place":"Well","prov":"Gld.","year":1963,"code":"SINSAG 0486","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/72785","original":"En daar nog iets over dan. As nou een vroue of een man of een kend vrijdags of zaoterdags gesturve was, dan wier 't niet begrave. Ston da lijk bove aarde op zondag, dan kreeg de hier op 't dorp binne zes weke weer unne dode.","lang":"Gelders","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","6 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":6},"on_success":{"chime":6,"digit":{"value":6,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":2,"drawers":[{"id":"2-1","type":"P4","difficulty":1.7442,"rank":0.8621,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"BOEKV094","role":"top","render":{"description":"Een vader en een zoon leven in een hol onder de grond. Om voorbijgangers te kunnen bestelen en vermoorden spannen ze een touw met een bel over de weg zodat de voorbijgangers kunnen horen. Op een dag komt een meisje langs.","place":"Amen","prov":"Dr.","year":1890,"code":"SINSAG 0161","initials":"G.J.B.","url":"https://www.verhalenbank.nl/items/show/34975","half":"top"},"home":"2-1"},{"id":"c2","story_id":"LYST041","role":"distractor","render":{"description":"Ze schrikken heel erg omdat ze denken dat het de onheilbrengende gedaante van een wit wief is. Later zien ze dat de gedaante geen wit wief is maar en witte geit die met zijn poten tegen de boom aan staat te eten van de bladeren.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c3","story_id":"KOOIJMAN0237","role":"distractor","render":{"description":"Als men 's nachts deze boomgaard betreedt kan men een witte vrouw op een varken tegenkomen. Omdat deze vrouw hier rondspookt kan de boer geen personeel vinden.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c4","story_id":"LYST291","role":"distractor","render":{"description":"Toch keert hij met een zak vol goud terug. Hij trouwt met de dochter van een rijke boer. Omdat de boerenzoon nog steeds in de macht van het witte wief is, bedenkt de vrouw van de boerenzoon en plan. Ze verkleedt zich als jongen en laat zich door het witte wief achtervolgen. Het witte wief overschrijdt hierdoor de grens van haar gebied en valt in handen van een man die haar weet te verdrinken.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c5","story_id":"BOEKV094","role":"bottom","render":{"description":"De zoon wil haar niet vermoorden omdat hij haar als vrouw wil. Een jaar lang laten vader en zoon het meisje niet alleen, maar na een jaar moeten ze toch samen naar buiten. Het meisje weet te vluchten. De zoon rent haar achterna en gooit met een bijl naar haar, maar hij raakt haar niet. Het meisje vertelt alles aan de schout, en de twee moordenaars worden onthoofd. Op de plek waar de twee zoveel mensen hebben vermoord, spoken de slachtoffers nu nog als witte wijven rond.","half":"bottom","code":"SINSAG 0161"},"home":"2-1"},{"id":"c6","story_id":"ENGELB_13_014","role":"distractor","render":{"description":"De man kan de boerderij binnengaan, de Hun gooit hem de bijl na, die in de deurpost terechtkomt.","half":"bottom","code":"SINSAG 0161"},"home":"2-1"},{"id":"c7","story_id":"CBOEK305","role":"distractor","render":{"description":"Als iemand haar rust verstoort, draait ze hem de nek om. Een sterke man gaat 's nachts naar het kasteel waar ze rondspookt en verdelgt haar voorgoed.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c8","story_id":"CJ005402","role":"distractor","render":{"description":"In het Zwagerbosch zag hij ineens vijf vrouwen staan met puntmutsen op en lange witte rokken aan. Het was bladstil maar de pluimen van de mutsen waaiden heen en weer. Hij werd doodsbenauwd en ging naar de boerderij van de oude Bearn. Toen ze samen gingen kijken waren de vrouwen weg.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c9","story_id":"VODA_035_14","role":"distractor","render":{"description":"De oude knecht is bang. Een jonge, onverschrokken knecht biedt aan om vanaf nu de paarden naar de wei te brengen en weer op te halen. Op een dag ziet ook de jonge knecht een brandend kaarsje op het damhek en twee zwevende dames. De paarden zijn onrustig. De knecht slaat het kaarsje van het hek en de twee dames zijn meteen verdwenen. De paarden zijn weer kalm. Vanaf dat moment wordt de jonge knecht echter nacht na nacht gekweld door de witte dame die haar lichtje terug wil en na zes weken sterft hij hierdoor.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c10","story_id":"TINNEV065","role":"distractor","render":{"description":"Het groepje begint te rennen. Als ze uitgerend zijn vertelt de eerste man dat hij een 'grijze juffer' had gezien.","half":"bottom","code":"SINSAG 0310F"},"home":"2-1"},{"id":"c11","story_id":"LYST280","role":"distractor","render":{"description":"Omdat hij hen beledigt, achtervolgt een van hen hem. De knecht kan net een huis binnenvluchten. De bijl die het Witte Wief gooide komt terecht in de stiepel.","half":"bottom","code":"SINSAG 0161"},"home":"2-1"},{"id":"c12","story_id":"TINNEV038","role":"distractor","render":{"description":"Ze dansen totdat de man niet meer kan en dood neervalt.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c13","story_id":"CJ001413","role":"distractor","render":{"description":"Hij heeft zijn tante vermoord om haar geld en sinds die tijd spookt het er. Dit alles gebeurt dichtbij de plek waar het huis van sterke Hearke heeft gestaan.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het onderste stuk noemt ‘meisje’ opnieuw.","Het nummer is SINSAG 0161. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c5"},"on_success":{"fuse":["c1","c5"],"stack":["c1","c5"]},"found_card":{"card":"c5"}},{"id":"2-2","type":"P3","difficulty":1.3541,"rank":1.004,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ112315","role":"member","render":{"description":"Op een spookplaats dolen twee witte meisjes rond. Ook op een andere plaats zou zo'n witte juffer gespookt hebben.","place":"De Westereen","prov":"Fr.","year":1974,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/30078","original":"Op it Skier spoeken twa famkes, dy wienen hielendal yn 't wyt. Om ien ûre yn 'e nacht wienen se warber. In man hat se dêr sjoen, hy hat it my sels forteld.\nDer mat hjir ek in wite juffer spoeke ha.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c2","story_id":"CJ057202","role":"member","render":{"description":"Onder Westergeest spookte altijd een witte juffrouw.","place":"Kollumersweach","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25824","original":"Oan 'e Wâlddyk ûnder Westergeast, dy kant nei Beintema's hûs op spûke altyd in wite juffer.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c3","story_id":"KEUNING003202","role":"intruder","render":{"description":"Spotter met duivel wordt opgetild en heen en weer gesmeten.","place":"Jistrum","prov":"Fr.","year":1962,"code":null,"initials":"S.K.","url":"https://www.verhalenbank.nl/items/show/130981","original":"K. wier in ûnminske. Hy sloech syn wiif, hy forsoepte syn lean en hy swetste en flokte, dat it hwat die. Op in joun let roun hy op de Tilleloane en rôp, dat hy boppe Eestrum roun fleane soe as de duvel. Ynienen waerd hy opnaem en in kear of hwat hinne en wer oer de loane smiten. Doe rôp hy, dat hy it nea wer dwaen soe.","lang":"Fries","front":"original","uncatalogued":true},"home":"cab:5"},{"id":"c4","story_id":"CJ111314","role":"member","render":{"description":"Voor rondspokende witte juffers hoef je niet bang te zijn. De witte spookvrouwen kunnen verdreven worden, de zwarte niet.","place":"De Westereen","prov":"Fr.","year":1974,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/29719","original":"Men heart wolris fan wite juffers dy't spoekje. Dêr hoeft men net bang foar to wêzen. Wyt kin fordreaun wurde, mar swart net.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Jistrum hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c1","c2","c4"]}},{"id":"2-3","type":"R2","difficulty":1.0967,"rank":0.8305,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"LYST075","role":"card","render":{"description":"Op een bruiloft merkt een van de gasten op dat ze zijn vergeten de witte wieve uit te nodigen. Wanneer iemand spottend de witte wieve roept, wordt er een bijl naar zijn hoofd gegooid. Hij kan net op tijd naar binnen vluchten. De deur vertoont nog altijd de tekenen van de bijl. Het witte wiefke roept dat ze hem wel te pakken had kunnen nemen, als ze haar schoentje niet was verloren.","place":"Zenderen","prov":"Ov.","year":1953,"code":"SINSAG 0161","initials":"M.S.","url":"https://www.verhalenbank.nl/items/show/13289","original":"Parallel met het verhaal van de \"spinvisite\" loopt ook 't verhaal van de \"brulfte\" (bruiloft) waar een van de gasten tegen de \"brulfteneugers\" opmerkt dat hij de \"nögste noabers\" n.l. de \"witte wieve\" heeft vergeten. De \"brulfteneuger\" laat dat niet op zich zitten, gaat naar buiten en nodigt \"de witte wieve\" uit, op spottende toon. Hij wordt onmiddelijk achterna gezeten, vlucht nog net binnenshuis, terwijl hem de bijl nagegooid wordt en 'n snee in de niendeure maakt die nog aan de kleinkinderen van het bruidspaar vertoond wordt. Hier hoort ook weer dezelfde klacht over 't schoentje bij, dat niet was vastgestrikt.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c2","story_id":"KEUNING012603","role":"sill","render":{"description":"Op kerkhof zouden 's nachts twee witte vrouwen lopen.","place":"Genum","prov":"Fr.","year":1963,"code":"SINSAG 0310","initials":"S.K.","url":"https://www.verhalenbank.nl/items/show/131651","stain":"twee"},"home":"2-3"},{"id":"c3","story_id":"CJ018116","role":"card","render":{"description":"Op een bepaalde spookplaats spookt een wit wief.","place":"Sumar","prov":"Fr.","year":1967,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20270"},"home":"2-3"},{"id":"c4","story_id":"ENGELS003101","role":"card","render":{"description":"Heksen vliegen op bezemsteel, witte vrouwen zweven op rand van zeef.","place":"Helden","prov":"L.","year":1965,"code":"SINSAG 0310","initials":"G.G.E.","url":"https://www.verhalenbank.nl/items/show/210747","original":"Witte wiever:\nVroeger werd ons soms verteld, dat de heksen op een bezemsteel door de lucht vlogen. Witte wiever zweefden echter op een zeefrand (de houten spaanrand van een meelzeef) door de lucht.\n\nVerslag 55, Omzetting uit de Ned. taal in dialect van Helden, van de verhalen, ... onder no. L291-31. Helden, 10-12-1969\nWie we nag zo’n aankomende mèèdjes wore, vertèlde me, dét heksen dor de loocht vlogen op ennen beesemsjteel. Me sjpraak aug van Witte wiever. Die vlogen op enne zeve-rank dor de loocht. (Spaanrand van meelzeef).","lang":"Standaardnederlands; Limburgs","front":"description"},"home":"2-3"},{"id":"c5","story_id":"YPFOE070a","role":"card","render":{"description":"Op een kruispunt vlak bij Jistrum spookte het 's nachts. Een van Durk Jaringa's zonen kwam 's avonds na een feestje bij dat kruispunt langs en zag een witte gestalte vlak voor zich heen zweven. Hals over kop rende hij terug naar Jistrum. Een paar anderen hebben hem later langs het kruispunt naar huis gebracht, maar van de gestalte was niets meer te zien.","place":"Burgum","prov":"Fr.","year":1972,"code":"SINSAG 0310","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12146","original":"Wite juffers\nTe Jistrum, oan 'e noardkant, dêr krúst de Spoekloane de wei dy't fan Jistrum nei de Grinzerstrjitwei rint. Op dat krúspunt doogde it lang net. Dêr gong wol ris in wite gestalte dwers oer de wei, flak foar de minsken lâns. Ik wit noch wol, dat ien fan Durk Jaringa's jonges-se wennen oan 'e grutte strjitwei- de jûnes nei 'De Lindeboom' yn Jistrum west hie - sa hiet de jachtweide fan Jan van der Schors. It hie der tige gesellich west, hy hie in slokje dronke en om in oere of tsien, alven sette er op hûs yn. Hy kaam dêr op dy fjouwersprong en dêr gong dy wite gestalte flak foar him lâns. Hy waard sa kjel, dat hy stode hals oer de kop wer nei Justrum ta en dêr fûn er andergeloks noch lju yn 'e herberch. …","lang":"Fries","front":"description"},"home":"2-3"},{"id":"c6","story_id":"CJ064107","role":"card","render":{"description":"Vader en Evert Bergsma uit Tike zijn samen aan het bunzingvangen op de Gariperheide bij Tuijen.Er staan hoge bomen en dan ziet Evert twee bomen op zich afkomen. Ze gaan er omheen. Het zijn twee witte vrouwen met grote wijde witte rokken aan.","place":"De Tike","prov":"Fr.","year":1969,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/27201","original":"Heit en Evert Bergsma fan de Tike wienen us op in joun togearre oan 't murdejeijen. Sy wienen yn Gariperheide op 'e Tuijen. Dêr stienen hege beammen. Doe sei Evert ynienen: \"Hwat is dat dêr?\"\nDêr wienen twa, dy kommen op har ta.\n\"Wy matte dêr mar net lâns\", sei heit. Doe binne se dêr omhinne gien. 't Wienen twa wite froulju, dy hienen greate wide wite rokken oan.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een G.","Genum. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c2","object":"window","text":"Genum"},"on_success":{"digit":{"value":2,"card":"c2","word":"twee","stained":"c2"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P1","difficulty":1.1309,"rank":0.9121,"note":"Alle vier noemen ze hetzelfde ding. Dat wordt het etiket. Niet ‘een beest’ schrijven.","cards":[{"id":"c1","story_id":"EDJSL003","role":"card","render":{"description":"Boerenknecht zegt tegen zijn meisje dat hij een boodschap moet doen, en dat zij als ze een kwade hond tegenkomt die zijn zakdoek moet geven. Ze komt inderdaad een hond tegen, gooit de zakdoek naar de hond en vlucht. Tijdens het eten ziet men dat hij stukken van een zakdoek tussen zijn tanden heeft zitten. Bij het doorzoeken van zijn kamer wordt de riem gevonden waarmee iemand in een weerwolf verandert. Zodra de riem in het vuur is gegooid staat de knecht die ver weg aan het werk was, bij de oven en probeert in het vuur te springen. Na het verbranden van de riem is de knecht verlost.","place":"Bladel","prov":"N.-Br.","year":1894,"code":"SINSAG 0823","initials":"E.d.J.","url":"https://www.verhalenbank.nl/items/show/9505","original":"De weerwolf\nEr was eens een boerenknecht die soms een weerwolf was.\nDe knecht vrijde met een van de meiden, maar zij wist van de prins geen kwaad. Op een keer waren ze een eind buiten het dorp gaan wandelen. Toen ze op huis aangingen, viel de schemer in.\nOpeens had de knecht zin weerwolf te worden.\nHij zei tegen de meid: \"Ik moet hier even een boodschap doen. Loop jij maar vast door, ik haal je wel in. Mocht je een kwade hond tegenkomen, die je wil bijten, gooi hem dan mijn zakdoek toe. Dan heeft hij iets om zijn tanden in te zetten, terwijl jij ervandoor gaat.\"\nHij ging weg, en een poosje later zag ze een grote hond op zich afkomen. Ze gooide hem de zakdoek toe en zette het op een lopen. Het dier scheurde de zakdoek aan flarden en at hem op. …","lang":"Standaardnederlands","front":"original"},"home":"3-1"},{"id":"c2","story_id":"BOEKV179","role":"card","render":{"description":"Een jongeman is een weerwolf. Wanneer hij wandelt met zijn meisje, voelt hij aankomen dat hij zal veranderen. Hij stuurt haar verder en waarschuwt haar voor een grote hond. Zij moet hem zijn zakdoek toewerpen, dan kan het meisje vluchten. Later zien zij en haar familie echter dat de stukken zakdoek tussen de tanden van de jongeman zitten. Weerwolven hebben altijd een band om hun middel. De boer, bij wie de jongeman in dienst is, verbrandt de band. De weerwolf probeert nog in het vuur te komen, maar hij wordt tegengehouden. Wanneer de band verbrand is, is de jongeman weer een gewoon mens.","place":"Bladel","prov":"N.-Br.","year":1896,"code":"SINSAG 0823","initials":"G.J.B.","url":"https://www.verhalenbank.nl/items/show/35060","original":"Van een Weerwolf.\n\nOp de Achterste hoef woonde indertijd een boer, en die boer had een knecht, en dat was een weerwolf. Op een eigenaardige manier zijn ze daar achter gekomen.\nDie knecht vrijde met een meid uit de buurt. Eens waren die twee samen buiten dorps (1) geweest en 't was al tusschen licht en donker toen ze op huis aan gingen. Ze waren al niet meer zoo heel ver van huis toen voelde hij een onweerstaanbare lust om weerwolf te worden; maar de meid merkte het natuurlijk niet. Hij zei tot haar: \"Ik moet hier eens effekens (2) van den weg af bij genen boer zijn; ga gij maar door: ik zal u wel inhalen. Maar komt ge soms een kwaden hond tegen, die op u aan bijt, gooit hem dan mijn zakdoek toe; dien zal hij misschien wel vatten. …","lang":"Standaardnederlands","front":"original"},"home":"3-1"},{"id":"c3","story_id":"SINBRABSAG185","role":"card","render":{"description":"Een jongeman is een weerwolf. Wanneer hij wandelt met zijn meisje, voelt hij aankomen dat hij zal veranderen. Hij stuurt haar verder en waarschuwt haar voor een grote hond. Zij moet hem zijn zakdoek toewerpen, dan kan het meisje vluchten. Later zien zij en haar familie echter dat de stukken zakdoek tussen de tanden van de jongeman zitten. Hierdoor weten ze dat hij een weerwolf is.","place":"Bladel","prov":"N.-Br.","year":1933,"code":"SINSAG 0823","initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/46940","original":"No. 185. Op de Achterste hoef bij Bladel woonde indertijd een boer, en die boer had een knecht, en dat was een weerwolf. Op 'n vreemde manier zijn ze dat aan de weet gekomen. Die knecht vrijde met een meid uit de buurt. Eens waren die twee samen buitendorps geweest en 't was al tusschen licht en donker, toen ze op huis aan gingen. Ze waren al niet ver meer van huis toen hij een onweerstaanbaren lust voelde om weerwolf te worden; maar de meid merkte dat natuurlijk niet. Hij zei tot haar: \"Ik moet hier eens effekens van den weg af bij genen boer zijn, ga gij maar door: ik zal oe wel inhalen. Maar komt ge soms een kwaden hond tegen, die naar oe bijt, gooit hem dan mijn zakdoek toe; dien zal hij wel vatten. …","lang":"Standaardnederlands","front":"original"},"home":"3-1"},{"id":"c4","story_id":"LYST009","role":"card","render":{"description":"Een paartje loopt 's avonds te wandelen. De jongen moet zijn behoefte doen, maar voordat hij de bosjes in verdwijnt adviseert hij het meisje om, als een beest haar zou overvallen, het haar zakdoek voor de muil te werpen. Er komt inderdaad een gevaarlijk beest op het meisje af. Ze gooit haar zakdoek voor zijn bek en het beest verscheurt hem. Als de jongen weer terugkomt ziet het meisje dat hij resten van haar zakdoek tussen zijn tanden heeft zitten. Ze weet nu dat hij een weerwolf is en zegt dat ook tegen hem. De jongen verdwijnt en is nooit meer terug gekomen.","place":"Erp","prov":"N.-Br.","year":1953,"code":"SINSAG 0823","initials":"F.W.J.S.","url":"https://www.verhalenbank.nl/items/show/13223","original":"De Weerwolf\nEen vrijer bracht 's avonds z'n meisje naar huis. Onderweg zei ie: \"Ik moet even mijn behoefte doen. Als je in tussentijd een dier of zoiets op je af ziet komen, gooi het dan je zakdoek voor z'n kop.\" Toen de jongen weg was, kwam er een dier op het meisje aangelopen. Ze slingerde haar zakdoek voor z'n muil en het beest verscheurde hem. Even later kwam de jongen terug en hij vroeg zijn meisje of er iets gebeurd was. Ze vertelde wat er was voorgevalllen en terwijl keek ze hem strak aan. Toen zei ze hem: \"Ik geloof, dat jij het beest bent geweest, want je hebt de stukken zakdoek nog tussen je tanden zitten\" Onmiddellijk was de vrijer verdwenen, en het meisje heeft hem nooit teruggezien.","lang":"Standaardnederlands","front":"original"},"home":"3-1"}],"hints":["Lees de vier nog eens. Let op wat er in elk van de vier vóórkomt, niet op wat erin gebeurt.","Het is een voorwerp.","Begint met een Z. 7 letters."],"lock":{"kind":"word","salt":"471a2ca754b545a5","accepted_hashes":["9443c9165bc5868e5fd6f431d80b64d16cb4b29a86e78f05e184709a0da8c2bc","a28ba0c8ac766e1df01de6d058079ccee786680a7a1c4a348b653d66031bafe1"]},"on_success":{"print_label":true,"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c4"}},{"id":"3-2","type":"P3","difficulty":1.1214,"rank":0.543,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ115519","role":"member","render":{"description":"Een weerwolf is iemand die nooit verzadigd raakt: hij blijft maar dooreten. Één van zeven jongens uit een huishouden is een weerwolf.","place":"Houtigehage","prov":"Fr.","year":1977,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/31124","original":"In wjerwolf is ien dy't net sêd kin. 't Kin neat skele hoefolle er hawn hat, hy kin altyd wol wèr ite. Ien út in húshâlding fan sawn jonges is in wjerwolf.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c2","story_id":"CJ046513","role":"member","render":{"description":"Van zeven in leeftijd op elkaar volgende jongens, is er één weerwolf of een duivelbanner.","place":"Boelenslaan","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24459","original":"Fan ien fan 'e sawn jonges, dêr't net in fanke tusken is, is ien in wearwolf of in duvelbanner.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c3","story_id":"CJ054504","role":"member","render":{"description":"Één van zeven in leeftijd op elkaar volgende jongens is een weerwolf. De verteller vertelt over een jongen - één van zeven zonen - die een weerwolf is en de behoefte heeft allerlei dingen te verscheuren.","place":"Boelenslaan","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25484","original":"Ien fan sawn opelkoarfolgjende jonges is in wjerwolf.\nYn 'e Moedershoeke, hjir yn 'e Boelensloane wenne Brant Veenstra. Dy hie sawn jonges. Ien fan dy jonges is Hindrik. Dat wie in wjerwolf. Syn eigen heit sei: \"Hindrik is in raren, 't is in forskuorreling.\"\nOp in kear siet er op 't hûske. Syn broer Germ pleage him oan 'e bûtenkant. Doe fleach Hindrik sa fan 't hûske ôf mei de broeken by 't gat del op syn broer ta en seamde him ôf.\nHy ropte soms mei de tosken de bûsdoeken útelkoar.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"CJ009726","role":"intruder","render":{"description":"Witte wieven spoken meestal op houten planken.","place":"Harkema","prov":"Fr.","year":1966,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17542","uncatalogued":true},"home":"cab:2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Harkema hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c4","cabinet":2},"on_success":{"trail_note":2,"unlock_cabinet":2,"stack":["c1","c2","c3"]}},{"id":"3-3","type":"R3","difficulty":1.0596,"rank":0.5128,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"LYST189","role":"card","render":{"description":"Drie mensen vertellen dat zij 's avonds laat een grote hond met vurige ogen zijn tegengekomen, die bij hen op de rug sprong. Pas bij de grens van het stuk land sprong hij eraf en verdween. De hond verdween bij een boerderij die al als \"niet pluis\" bekend stond, omdat de knecht van die boerderij vertelde dat de koeien enkele malen om klokslag middernacht opsprongen terwijl de staldeuren vanzelf opensprongen.","place":"Puiflijk","prov":"Gld.","year":1957,"code":"SINSAG 0801","initials":"C.v.d.P.","url":"https://www.verhalenbank.nl/items/show/13453","original":"Spookdieren\nMij is eens door drie verschillende personen op zeer verschillende tijden meegedeeld dat op de Waaldijk tussen Boven-Leeuwen en Druten 's avonds in pikdonker plotseling een abnormale grote hond, die plotseling verscheen, hen zwijgend met vurige ogen volgde en even plots aan de grens van Druten verdween. Beide personen waren niet bijgelovig maar hadden van angst 't zweet op de rug staan van angst, temeer daar de hond verdween bij een boerderij waar 't niet \"pluis\" scheen te zijn. Een knecht op deze boerderij vertelde mij eens hoe verscheidene malen 's nachts de koeien om klokslag 12 uur opsprongen en staldeuren openvlogen zonder 'n aanwijsbare oorzaak. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c2","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c3","story_id":"EDJSL012","role":"card","render":{"description":"Een dagloner keert terug naar huis en ziet een ploeg zonder paard of man op zich af komen. De ploeg verandert van gedaante: het is de keuterboer, die voor hem staat. De keuterboer smeekt de man hem niet te verraden. \nIn de hooitijd werken de twee mannen samen. Als de keuterboer slaapt komt er een mol uit zijn nek. De keuterboer kotst liters bloed. In de wei worden de resten van een kalf gevonden; alleen een paar afgekloven botten zijn over. De keuterboer sterft. De pastoor moet erbij komen om de kist naar het kerkhof te kunnen dragen.","place":"Didam","prov":"Gld.","year":1980,"code":"SINSAG 0804","initials":"E.d.J.","url":"https://www.verhalenbank.nl/items/show/9514","original":"Mol, de weerwolf\nEen keuterboer, die Mol heette, werd altijd uitgescholden:\n\"Bierpoep! Twee emmers vol snijbonen en nog maar wind!\"\nDat kwam omdat hij zoveel at.\nKarels, een dagloner, keerde 's avonds laat dwars door het veld terug naar huis, toen hij een ploeg zonder paard of man op zich af zag komen. Hij trok zijn mes, maar het ketste af op het ploegijzer. De ploeg veranderde van gedaante, en in de man die voor hem stond, herkende hij Mol.\nDeze viel op zijn knieën en smeekte hem niet te verraden. Hij zou Karels een mud boekweit en een mud rogge geven.\n\"Van jou, weerwolf, wil ik geen boekweit of rogge,\" zei de boerenknecht. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c4","story_id":"KOOIJMAN1182","role":"card","render":{"description":"Er woonde vroeger in Blokland een vrouw en die beweerde dat ze iedere avond de weerwolf buiten tekeer hoorde gaan tussen half elf en twaalf uur.","place":"Blokland","prov":"Utr.","year":1963,"code":"SINSAG 0804","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/72678","original":"De weerwolf, de weerwolf. Nou je 't zegt. D'r woonde vroeger in Blokland een vrouw. Die woonde daar op d'r eige alleen. En die vrouw die beweerde, ze hoorde iedere avond de weerwolf buite tekeergaan. Iedere avond tusse half elf en twaalf uur. Ze sloot alles d'r voor af.","lang":"Utrechts","front":"description"},"home":"3-3"},{"id":"c5","story_id":"CJ007505","role":"door","render":{"description":"In een gezin van zeven jongens is de oudste, jongste of middelste een weerwolf, een man die er uit ziet als een beest en moet moorden.","place":"Kollumersweach","prov":"Fr.","year":1966,"code":"TM 3107","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/16994","original":"As der yn in húshâlding sawn jonges binne, is de âldste of de jongste of de middelste in wjerwolf. In wjerwolf, dat is in man, dy't de natuer hat fan in beest; ien dy't formoardzje mat.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c5","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c1"},"stack":["c1","c2","c3","c4"]}}]},{"id":4,"label":"Spoken","digit":3,"drawers":[{"id":"4-1","type":"P5","difficulty":0.6696,"rank":0.25,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"WEV009505","role":"variant","render":{"description":"Om middernacht spookt geest van een vermoorde rond en spat het bloed op op de plaats van de moord. Jongen durft dan niet over de rechterschouder te kijken.","place":"Stadskanaal","prov":"Gr.","year":1965,"code":"SINSAG 0450","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44586"},"home":"4-1"},{"id":"c2","story_id":"WEV015701","role":"variant","render":{"description":"'s Avond laat merkt man dat achterdeur van stal open is en hoort gestommel, dat niet van de koeien komt. Boer vertelt dat vrouw die er is vermoord zo nu en dan spookt.","place":"Musselkanaal","prov":"Gr.","year":1967,"code":"SINSAG 0450","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/45797","original":"Mien voader kon kwoad zain en hef mie door veul van verteld. Hai dainde as jongkerel bie de boer. Op n keer kwam e wat loat in hoes. Dan gung e deur de achterdeure van de dele, umdat andere deurn dicht zatn. As hai dan dele opstapt, heurt hai n geluud, man zug niks. \n“Kou lös”, denkt e. Hai zöcht n schienvat op en gait de baistn bie langs. Man nee heur, alles is rustig. \n Zeker wat verbeeld, zo denkt hai. Nich laank loater overkomp hum t zulfde; weer gestommel op dele en t binnen gain koi-en, dai t doun. \nNon wait hai nich meer, wat e door van denkn mout. Wol wait hai wizze, dat e nooit meer deur de baanderdeure wil. \nAnder dag under t eetn proot hai dr over mit de boer. Dai zeg eerst niks. …","lang":"Gronings","front":"description"},"home":"4-1"},{"id":"c3","story_id":"CJ105507","role":"variant","render":{"description":"Men kan 's nachts wel eens een witte verschijning van een vermoorde vrouw zien.","place":"Opende","prov":"Gr.","year":1973,"code":"SINSAG 0450","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37578","original":"Mem fortelde, hjir yn 'e Pein hat in huzinge stien mei in gracht der by. Dêr is alris in frommeske formoarde woarn. Sûnt seach men dêr nachts in frou yn 't wyt troch de gracht hinne rinnen. Dat wie dat formoarde frommeske.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Groningen werd een tijdstip genoemd: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.D.","summary":true},"home":"4-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1965.","Op die kaart staat een tijdstip. Welk?"],"lock":{"kind":"word","salt":"471a2ca754b545a5","accepted_hashes":["144b6afe185930354e3d3d29aba207cabc3aaaa10e72982f38f57b271760ce17","b8bbf0934f83a37e5042ce31fbcfa0dd6f787972441bb0c9ec5c163bd8e7f6cc","d595de4feb2a87dae042b310e81b3ab07b7c2df39966d17f11b63d50598aad40","f6eb89ad271ea53f5e66ad567bdd18b12ef55664b50161bcaca495cd01341ea0"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.1065,"rank":0.515,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"SINBRABSAG078","role":"member","render":{"description":"In Aalst zag de dochter van een boerin een geest, terwijl ze de koe aan het melken was. Ze was erg bang en de volgende dag ging de knecht mee. Ook hij zag de geest. De geest kwam elke avond dichterbij en de pastoor zei dat ze aan de geest moesten vragen wat zijn begeerten zijn. De boerin, knecht en de dochter vroegen de geest naar zijn begeerten en hij vertelde dat hij een belofte had gedaan om een bedevaart te maken naar Kevelaar, maar die niet meer was nagekomen. Ze besloten om met z'n allen de bedevaart te maken. Na de reis was de geest verlost en kon hij naar de hemel.","place":"Voldijn","prov":"N.-Br.","year":1933,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/46713","original":"No. 78. Iederen avond ging de dochter van een boer uit Aalst met een paar meiden de koeien melken, tot zij op zekeren avond aan den rand van een bosch, op flinken afstand, een witte gedaante zag verschijnen. Ze werd bang en liep naar huis, zonder de koeien verder te melken. Ze kon niet spreken van angst en schrik, omdat ze niet wist wat 't was, en kwam hijgend van 't loopen thuis aan. De huisgenooten vroegen direct wat er aan de hand was, en toen zei ze, na tot bedaren gekomen te zijn, dat 't kon gaan zooals 't wilde, maar ze ging niet meer alleen melken, zoo was ze geschrokken. Den volgenden avond ging de knecht mee, omdat ze alleen niet meer wilde. Ze zagen dezelfde gedaante weer, maar nu kwam ze veel dichter bij. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c2","story_id":"SINBRABSAG080","role":"member","render":{"description":"Een arme bezembinder zag de geest van zijn vader, die kort geleden gestorven was, op de kruiwagen zitten. Zijn vader vertelde hem dat hij een bedevaart moest maken en brood aan de armen moest geven, zijn vader had namelijk een belofte gedaan die hij niet was nagekomen. Na deze woorden verdween zijn vader.","place":"Eersel","prov":"N.-Br.","year":1933,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/46715","original":"No. 80. Omstreeks 1840 ging de arme bezembinder R. v. G. uit Eersel hei snijden. Nadat hij zijn vracht op de kruiwagen geladen had, rustte hij in de Zanddreef wat uit. Toen hij zijn tocht wilde voortzetten zat de geest van zijn vader, die voor kort gestorven was, op z'n kruiwagen. Hij beval zijn zoon om een beevaart te doen en den armen een brood te geven, want hij had tijdens zijn leven, een belofte niet nagekomen. Daarop verdween de geest, zonder een spoor achter te laten. 2)","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"SINBRABSAG081","role":"member","render":{"description":"De geest van de pastoor vraagt aan een vroom persoon of zij een goed werk voor hem wilt doen, zodat hij in de hemel kan komen.","place":"Westerhoven","prov":"N.-Br.","year":1933,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/46716","original":"No. 81. Het gebeurde op het gehucht Loveren, anderen zeggen in het braambosch, onder Westerhoven. De pastoor was gestorven, en zijn geest verscheen aan een vroom kwezelken, en verzocht haar spoedig een goed werk voor hem te laten doen, dan zou hij zalig worden.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c4","story_id":"CJ039817","role":"intruder","render":{"description":"Man vraagt aan zijn verkering om een zakdoek, en verdwijnt daarmee. Bij terugkomst hangen rode draden van de zakdoek tussen zijn tanden. Hij bekent een weerwolf te zijn die af en toe iets moet verscheuren, en had om een zakdoek gevraagd om haar niet te verscheuren.","place":"Harkema","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/23534","original":"Der wienen in feint en in faem, dy wienen togearre út to riden.\nUnderweis lei de feint de swipe del en hy liet it hynder stilstean.\nDe faem sei tsjin 'e feint: \"Hwat silstû?\"\n\"Jow my de bûsdoek\", sei er. Doe joech se him in reade bûsdoek. Dêr gong er mei fuort.\nDoe't er in skoftsje fuort west hie, kom er werom. Doe hied er de reade triedden fan 'e bûsdoek tusken de tosken hingjen.\n\"Hwat hastû dien?\" sei se.\nDoe hied er bikend dat er in wjerwolf wie. Hy moest nou en dan hwat forskuorre. Dêrom hied er om 'e bûsdoek frege, oars hied er har forskuorre matten.\nDoe hat dy faem de forkearing gau út makke.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:3"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een weerwolf.","De kaart over Harkema hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c4","cabinet":3},"on_success":{"trail_note":1,"unlock_cabinet":3,"stack":["c1","c2","c3"]}},{"id":"4-3","type":"R4","difficulty":1.1229,"rank":0.3333,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"VODA_002_16","role":"top","render":{"description":"In een kasteel in de buurt van Eersel spookt het. Een dappere man uit het dorp gaat op onderzoek uit. Tijdens het wachten bakt hij pannenkoeken boven een vuurtje.","place":"Eindhoven","prov":"N.-Br.","year":1976,"code":"SINSAG 0401","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/69637","half":"top"},"home":"4-3"},{"id":"c2","story_id":"VODA_002_16","role":"bottom","render":{"description":"Elke keer dat een pannenkoek gaar is komt er een ledemaat uit de schoorsteen vallen totdat het om middernacht een skelet vormt dat tot leven komt. Het skelet wijst hem naar de kelder waar drie kisten goud staan. Als de kisten worden verdeeld onder de man, de kerk, en de armen kan de geest rusten.","half":"bottom","code":"SINSAG 0401","stain":"drie"},"home":"4-3"},{"id":"c3","story_id":"CJ060811","role":"half","render":{"description":"Op deze plek hangt later een blauw-wollen schort over de haag die voor de spook in plaats gekomen was. De heg staat vlakbij de Spookplaats.","half":"bottom","code":"SINSAG 0477"},"home":"4-3"},{"id":"c4","story_id":"LYST263","role":"half","render":{"description":"De sage gaat dat men rond middernacht in die bossen een witte dame ziet die vroeger op het kasteel heeft gewoond, ziet rondspoken","half":"bottom","code":"SINSAG 0450"},"home":"4-3"},{"id":"c5","story_id":"CJ100109","role":"half","render":{"description":"De vader zag niets, maar de hond rende doodsbang naar huis. De jongen zag de verschijning toen het land inrennen, en durfde later nooit meer op die plek te komen.","half":"bottom","code":"SINSAG 0478"},"home":"4-3"},{"id":"c6","story_id":"BRUIJNZILV012","role":"half","render":{"description":"Na sterk nadenken ziet hij voor zich dat hij de pot met geld onder een wilg heeft begraven. Moeder en zoon gaan graven, maar vinden niets. De toverknikker van het buurmeisje blijft na wegrollen liggen op de plaats waar de schat is begraven.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c7","story_id":"CJ019718","role":"half","render":{"description":"Op het laatst slaan er zelfs vlammen uit de kist. Er wordt gezegd dat de schatkist pas ophoudt met zakken, als er een witte bok over de plek heen rent.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘man’ opnieuw.","Het nummer is SINSAG 0401. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c2","object":"typewriter"},"on_success":{"fuse":["c1","c2"],"type_line":"Verteller: de vorige assistent.","digit":{"value":3,"card":"c1","word":"drie","stained":"c2"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
